UPDATE public.labs SET name_en = COALESCE(name_en, $en$Haedanghwa Photo Studio$en$), address_en = COALESCE(address_en, $en$1F, 288 Jemullyang-ro, Jung-gu, Incheon$en$), features_en = COALESCE(features_en, $en$Color development 5,000 won (13,000 won for 3 rolls), high-resolution scan option, black-and-white development and scan 12,000 won. Also works as an ID photo studio.$en$) WHERE name = '해당화사진관' AND region = '인천';

