UPDATE public.repair_shops SET name_en = COALESCE(name_en, $en$Speed Camera$en$), address_en = COALESCE(address_en, $en$Room 301, 3F, 2-1 Namdaemun-ro, Jung-gu, Seoul$en$), specialty_en = COALESCE(specialty_en, $en$Compact point-and-shoots$en$), description_en = COALESCE(description_en, $en$Friendly, well priced and thorough. Lately there is a bit of a backlog, though.$en$) WHERE name = '스피드카메라' AND region = '서울';
