UPDATE public.repair_shops SET name_en = COALESCE(name_en, $en$Jungang Camera$en$), address_en = COALESCE(address_en, $en$Unit 3, 1F, 7 Joyang-ro, Hongseong-eup, Hongseong-gun, Chungcheongnam-do$en$), specialty_en = COALESCE(specialty_en, $en$Leica, manual rangefinders$en$), description_en = COALESCE(description_en, $en$Run by master technician Kim Hak-won. Expect a wait and higher costs, but the quality is top-notch.$en$) WHERE name = '중앙카메라' AND region = '충남';
